)

mapper.select:
select resume_id AS resumeId, user_id AS userId, title, created_at AS createdAt,
hiddenIndustry, hiddenJob, hiddenCompanyType, companyName
from resume where user_id = #{userId}

mapper.update:
update resume set title = #{title}, name_kor = #{nameKor}, name_eng = #{nameEng}, name_han = #{nameHan},
birth_date = #{birthDate}, gender = #{gender}, phone_number = #{phoneNumber}, email = #{email}, address1 = #{address1}, address2 = #{address2},
veteran_status = #{veteranStatus}, veteran_number = #{veteranNumber}, disability_status = #{disabilityStatus}, disability_grade = #{disabilityGrade}, multicultural_status = #{multiculturalStatus}, north_defector = #{northDefector}, low_income_status = #{lowIncomeStatus},
military_service = #{militaryService}, military_branch = #{militaryBranch}, military_rank = #{militaryRank}, discharge_reason = #{dischargeReason}, enlist_date = #{enlistDate}, discharge_date = #{dischargeDate}, exemption_reason = #{exemptionReason}
where resume_id = #{resumeId} and user_id = #{userId}
